contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function driving the property check
    function run(
        address caller, // the address that will attempt to call setL1BlockValues (simulated by using delegatecall-like behavior: we check equality with DEPOSITOR_ACCOUNT via observable effect)
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        // Read values before the attempt
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequenceNumber = c.sequenceNumber();
        bytes32 before_batcherHash = c.batcherHash();
        uint256 before_l1FeeOverhead = c.l1FeeOverhead();
        uint256 before_l1FeeScalar = c.l1FeeScalar();

        // Try calling setL1BlockValues and capture whether it reverted.
        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read values after the attempt
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequenceNumber = c.sequenceNumber();
        bytes32 after_batcherHash = c.batcherHash();
        uint256 after_l1FeeOverhead = c.l1FeeOverhead();
        uint256 after_l1FeeScalar = c.l1FeeScalar();

        // General rule: if the call reverted, none of the public state fields changed;
        // if it did not revert, at least one field equals the corresponding input.
        // This captures that only the authorized depositor can update state and that a successful call applies inputs.
        assert(
            (reverted &&
                before_number == after_number &&
                before_timestamp == after_timestamp &&
                before_basefee == after_basefee &&
                before_hash == after_hash &&
                before_sequenceNumber == after_sequenceNumber &&
                before_batcherHash == after_batcherHash &&
                before_l1FeeOverhead == after_l1FeeOverhead &&
                before_l1FeeScalar == after_l1FeeScalar
            )
            ||
            (!reverted && (
                after_number == _number ||
                after_timestamp == _timestamp ||
                after_basefee == _basefee ||
                after_hash == _hash ||
                after_sequenceNumber == _sequenceNumber ||
                after_batcherHash == _batcherHash ||
                after_l1FeeOverhead == _l1FeeOverhead ||
                after_l1FeeScalar == _l1FeeScalar
            ))
        );
    }

    receive() external payable {}
}

