contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function driving the property check
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        // No precondition on parameters

        // Observe sequenceNumber before
        uint64 before_seq = c.sequenceNumber();
        // Observe contract balance before
        uint256 before_balance = address(c).balance;

        // Attempt the state-changing call and capture whether it reverted
        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe sequenceNumber after and contract balance after
        uint64 after_seq = c.sequenceNumber();
        uint256 after_balance = address(c).balance;

        // General rule:
        // - If the call reverted then sequenceNumber did not change.
        // - If the call succeeded then sequenceNumber equals the provided _sequenceNumber.
        // In all cases, the contract's ETH balance is unchanged by the call.
        assert(
            (reverted && after_seq == before_seq && after_balance == before_balance)
            || (!reverted && after_seq == _sequenceNumber && after_balance == before_balance)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function driving the property check
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        // No precondition on parameters

        // Read all observable fields before the call
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequence = c.sequenceNumber();
        bytes32 before_batcher = c.batcherHash();
        uint256 before_overhead = c.l1FeeOverhead();
        uint256 before_scalar = c.l1FeeScalar();
        uint256 before_balance = address(c).balance;

        // Attempt the possibly-reverting state-changing call and record whether it reverted
        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read all observable fields after the call
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequence = c.sequenceNumber();
        bytes32 after_batcher = c.batcherHash();
        uint256 after_overhead = c.l1FeeOverhead();
        uint256 after_scalar = c.l1FeeScalar();
        uint256 after_balance = address(c).balance;

        // General invariant:
        // - If the call reverted then all observed fields and balance remain equal to before-values.
        // - If the call succeeded then all observed fields equal the corresponding input parameters and balance is unchanged.
        assert(
            (reverted
                && after_number == before_number
                && after_timestamp == before_timestamp
                && after_basefee == before_basefee
                && after_hash == before_hash
                && after_sequence == before_sequence
                && after_batcher == before_batcher
                && after_overhead == before_overhead
                && after_scalar == before_scalar
                && after_balance == before_balance)
            || (!reverted
                && after_number == _number
                && after_timestamp == _timestamp
                && after_basefee == _basefee
                && after_hash == _hash
                && after_sequence == _sequenceNumber
                && after_batcher == _batcherHash
                && after_overhead == _l1FeeOverhead
                && after_scalar == _l1FeeScalar
                && after_balance == before_balance)
        );
    }

    receive() external payable {}
}
